  body += noise * 0.022 * mix(0.6, 1.0, dark);

  // Tout ce que la lumi\xE8re ajoute (feuille, nacre, \xE9clats) est cumul\xE9, puis compos\xE9 selon le papier.
  var foil = noise * light * 0.085 + light * (vec3f(0.045) + tint * 0.065);
  let dx = dpdx(p);
  let dy = dpdy(p);
  let mark = engrave(p, aa, params.seed, params.sys, params.time, dx, dy);
  let markDiffraction = tinted(diffraction(mark.across, lightAndView, 1.5)) * illumination;
  let pearlPhase = dot(lightAndView, vec2f(0.48, -0.32)) + p.y * 0.32 + dot(mark.across, lightAndView) * 0.2;
